import{_ as p,a0 as u,w as s,s as a,ao as r,I as e,x as n,a1 as l,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse(`{"title":"為什麼我們不應該接受低劣的Linux移植遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"為什麼我們不應該接受低劣的Linux移植遊戲 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼我們不應該接受低劣的Linux移植遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼我們不應該接受低劣的Linux移植遊戲 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140528 Why We Shouldn't Accept Bad Linux Ports","title":"為什麼我們不應該接受低劣的Linux移植遊戲","tag":"201406","desc":""},"relativePath":"201406/20140528 Why We Shouldn't Accept Bad Linux Ports.md","filePath":"[post].md"}`),x={name:"201406/20140528 Why We Shouldn't Accept Bad Linux Ports.md"};function d(m,t,L,w,T,f){const i=u("Link");return s(),a("div",null,[t[14]||(t[14]=r('<h1 id="為什麼我們不應該接受低劣的linux移植遊戲" tabindex="-1">為什麼我們不應該接受低劣的Linux移植遊戲 <a class="header-anchor" href="#為什麼我們不應該接受低劣的linux移植遊戲" aria-label="Permalink to “為什麼我們不應該接受低劣的Linux移植遊戲”">​</a></h1><p>由於最近The Witcher 2的慘敗，我想寫下些想法，為什麼我們不應該接受來自開發人員的品質低劣的移植遊戲。</p><p>最近幾年在我們的Linux遊戲庫裏面有如此多遊戲，以至於你現在可以看到來自Linux玩家的評論“我們已經有很多遊戲了！”可能這些聲音來自很多像你一樣的人。感謝Valve 和 Steam，之前我們從來沒有得到過這麼多的開發者的關注。</p><p>同樣由於開發者的推進，我們看見了伴隨而來的各種移植遊戲，坦率地説，它們的質量十分的低劣，或者説對於大多數人們來説根本不值得去看一眼。</p><p>現在的問題就是，如果我們繼續接受這種低水平質量的移植，Linux就會贏得一個遊戲質量水平低的名聲。請認真考慮一下這樣的後果吧！</p><p>再想像一下，如果那些AAA級的開發者給Linux推送了大量遊戲，其中使用了The Witcher2 移植所用的“eON”技術。看起來就像我們有了大量開發者，突然之間Linux有很多大牌遊戲了。然後你可以看見大量的人嘗試Linux，卻發現它們的遊戲在同等硬件之下卻有着糟糕的畫面，就會給他們一個印象，Linux對遊戲不友好。這對我們所有人都很糟糕。</p><p>我已經看見許多人説“這個工具包用於移植沒關係？”。這在我的眼裏看來是一個非常天真的想法。當然，這有關係， 它意味Linux的遊戲裏面的光線和白天的不同品質。這就直接追溯到我上面關於Linux遊戲的觀點上了。</p><p>你可以堅持説工具包沒有關係，而且使用任何一個你想用的比較/類比的效果，但如果工具包是導致問題的根源，就像我們説的計算機佔用了99%的處理能力的軟件一樣，是的，它當然有關係！</p><p>如今，我已經看見許多來自其他主流網站發表的評論，“我們應該接受它們並且作感謝狀，我們畢竟擁有了它們”。那些都是鼠目寸光的人們説的胡話！</p><p><img src="http://www.gamingonlinux.com/uploads/articles/article_images/1401025331gol2.jpg" alt=""></p><p>想想，那些開發者和發行商看到那些低劣的Linux移植遊戲也能被接受時，他們的腦裏只有錢。消費者對Linux遊戲的感知就會進一步惡化，就是因為這些低劣的移植品。</p>',11)),e("p",null,[t[1]||(t[1]=n("我可以接受這些來自開發者的移植，畢竟是我運營着這個網站（ ",-1)),l(i,{href:"http://www.gamingonlinux.com/"},{default:o(()=>[...t[0]||(t[0]=[n("http://www.gamingonlinux.com/",-1)])]),_:1}),t[2]||(t[2]=n(" ）。但是，如果我作為一個消費者不願意為在windows運行挺好的遊戲買單，而卻為在Linux慢得像蝸牛一樣的遊戲買單？我會麼？你會麼？",-1))]),t[15]||(t[15]=e("p",null,"最後附加的一點：你絕不應該攻擊一個試圖在社區裏面解決問題的開發者，這樣是不可以的。反饋是很好，罵人卻是很幼稚的，這會使得Linux看起來更糟。",-1)),t[16]||(t[16]=e("hr",null,null,-1)),e("p",null,[t[4]||(t[4]=n("via: ",-1)),l(i,{href:"http://www.gamingonlinux.com/articles/why-we-shouldnt-accept-bad-linux-ports.3765"},{default:o(()=>[...t[3]||(t[3]=[n("http://www.gamingonlinux.com/articles/why-we-shouldnt-accept-bad-linux-ports.3765",-1)])]),_:1})]),e("p",null,[t[7]||(t[7]=n("譯者：",-1)),l(i,{href:"http://www.vicyu.net"},{default:o(()=>[...t[5]||(t[5]=[n("Vic020",-1)])]),_:1}),t[8]||(t[8]=n(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=n("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原創翻譯，",-1)),l(i,{href:"http://linux.cn/"},{default:o(()=>[...t[10]||(t[10]=[n("Linux中國",-1)])]),_:1}),t[13]||(t[13]=n(" 榮譽推出",-1))])])}const A=p(x,[["render",d]]);export{h as __pageData,A as default};
